// === Tab: mySketch.js ===
function setup() 
{
	createCanvas(1500, 600,WEBGL);
	background(100);
}

let angle = 0;
let pointCount = 50 
let diameter=500
let counter=0

function draw() 
{
	counter=counter+.05
	diameter=diameter-counter

	translate(0,400,-2300)

	rotateX((3.14/2)+.8)
	rotateY(.1)
	rotateZ(counter)
	push()
	for(let i = angle; i < radians(360 + angle) ; i += radians(360 / pointCount) )
	{
		translate(0,counter,0)
		let x = diameter / 2 * Math.cos(i) + 0;
		let y = diameter / 2 * Math.sin(i) + 0;
		strokeWeight(random(5))
		stroke(255-counter)
		if(counter>round(random(16,25))) noFill()
		else fill(random(255))
		rect(x,y,10+counter*13) 
	}
	pop()

	rotateY(3.14)

	push()
	for(let i = angle; i < radians(360 + angle) ; i += radians(360 / pointCount) )
	{
		translate(0,counter,0)
		var x = diameter / 2 * Math.cos(i) + 0;
		var y = diameter / 2 * Math.sin(i) + 0;
		strokeWeight(random(5))
		stroke(counter)
		if(counter>round(random(16,25))) noFill()
		else fill(random(255))
		rect(x,y,10+counter*13) 
	}
	pop()
}

